{
  "name": "opencode-todo-progress",
  "version": "0.1.3",
  "description": "Persistent todo progress bar for the opencode TUI — shows ▓▓▓▓░░░░░░ 3/10 · current task next to the model name.",
  "type": "module",
  "license": "MIT",
  "author": "satas20 <ata.ayyildiz@outlook.com>",
  "keywords": ["opencode", "tui", "plugin", "todo", "progress", "statusbar"],
  "homepage": "https://github.com/satas20/opencode-todo-progress",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/satas20/opencode-todo-progress.git"
  },
  "bugs": {
    "url": "https://github.com/satas20/opencode-todo-progress/issues"
  },
  "publishConfig": {
    "access": "public"
  },
  "exports": {
    "./tui": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "files": ["dist"],
  "engines": {
    "opencode": ">=1.17"
  },
  "scripts": {
    "build": "bun run build.ts && tsc",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "bun run build"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.17",
    "@opentui/solid": "*",
    "solid-js": "*"
  },
  "devDependencies": {
    "@opencode-ai/plugin": ">=1.17",
    "@opentui/solid": "^0.4.3",
    "solid-js": "*",
    "typescript": "^5"
  }
}
